type CompareSkuUpcMapping struct {
	name string
}

type compareSkuUpcSample struct {
	SkuItem string
	DbUpcs  []string
}

func NewCompareSkuUpcMapping() *CompareSkuUpcMapping {
	return &CompareSkuUpcMapping{
		name: "临时对比库存 SKU UPC 映射与 PIM UPC",
	}
}

func (job *CompareSkuUpcMapping) Run(c ctx.Context, handler *xjob.JobHandler) error {
	specs := handler.Runner().Specs()
	if len(specs) < 1 {
		return fmt.Errorf("usage: compareInventorySkuUpcMapping <enterprise_id> [sample_size] [batch_no] [output_path]")
	}

	enterpriseId, err := strconv.ParseInt(specs[0], 10, 64)
	if err != nil {
		return fmt.Errorf("invalid enterprise_id %s: %w", specs[0], err)
	}

	sampleSize := defaultCompareSkuUpcSampleSize
	if len(specs) >= 2 && strings.TrimSpace(specs[1]) != "" {
		sampleSize, err = strconv.Atoi(specs[1])
		if err != nil || sampleSize <= 0 {
			return fmt.Errorf("invalid sample_size %s", specs[1])
		}
	}

	batchNo := ""
	if len(specs) >= 3 {
		batchNo = strings.TrimSpace(specs[2])
	}
	if batchNo == "" {
		batch, err := microScrmDao.NewInventorySkuUpcImportBatchDao().GetActiveSuccessBatch(c, enterpriseId)
		if err != nil {
			return err
		}
		if batch.BatchNo == "" {
			return fmt.Errorf("no active success inventory sku upc batch found")
		}
		batchNo = batch.BatchNo
	}

	outputPath := filepath.Join("work", fmt.Sprintf("inventory_sku_upc_compare_%d_%s.csv", enterpriseId, time.Now().Format("20060102150405")))
	if len(specs) >= 4 && strings.TrimSpace(specs[3]) != "" {
		outputPath = strings.TrimSpace(specs[3])
	}

	manualSkuItems := parseManualCompareSkuItems(manualCompareSkuItems)
	var samples []compareSkuUpcSample
	if len(manualSkuItems) > 0 {
		samples, err = job.pickManualSamples(c, enterpriseId, batchNo, manualSkuItems)
	} else {
		samples, err = job.pickSamples(c, enterpriseId, batchNo, sampleSize)
	}
	if err != nil {
		return err
	}
	if len(samples) == 0 {
		return fmt.Errorf("no sku samples found for batch_no=%s", batchNo)
	}

	if err = os.MkdirAll(filepath.Dir(outputPath), 0755); err != nil {
		return err
	}
	file, err := os.Create(outputPath)
	if err != nil {
		return err
	}
	defer file.Close()

	writer := csv.NewWriter(file)
	defer writer.Flush()
	if err = writer.Write([]string{"sku_item", "db_upcs", "pim_upcs", "only_in_db", "only_in_pim", "matched"}); err != nil {
		return err
	}

	brandSvc := sourceSvc.NewBrandService()
	for _, sample := range samples {
		pimUpcs, err := brandSvc.GetUpcListBySkuItem(c, enterpriseId, sample.SkuItem)
		if err != nil {
			return fmt.Errorf("query pim upcs failed sku_item=%s: %w", sample.SkuItem, err)
		}
		onlyInDB, onlyInPIM, matched := diffUpcCodes(sample.DbUpcs, pimUpcs)
		err = writer.Write([]string{
			sample.SkuItem,
			strings.Join(normalizeUpcCodes(sample.DbUpcs), "|"),
			strings.Join(normalizeUpcCodes(pimUpcs), "|"),
			strings.Join(onlyInDB, "|"),
			strings.Join(onlyInPIM, "|"),
			strconv.FormatBool(matched),
		})
		if err != nil {
			return err
		}
	}

	writer.Flush()
	if err = writer.Error(); err != nil {
		return err
	}

	log.Info(c).Msgf("inventory sku upc mapping compare finished enterprise_id=%d batch_no=%s sample_size=%d output=%s", enterpriseId, batchNo, len(samples), outputPath)
	return nil
}

func (job *CompareSkuUpcMapping) pickSamples(c app.Ctx, enterpriseId int64, batchNo string, sampleSize int) ([]compareSkuUpcSample, error) {
	db := app.DB()
	mappingModel := microScrmModel.InventorySkuUpcMappingModel{}
	branchDao := dao.Dao{DB: db}
	var skuItems []string
	err := db.WithContext(c).
		Scopes(branchDao.BranchDataBase(enterpriseId, mappingModel.TableName())).
		Model(mappingModel).
		Where("batch_no = ? AND deleted_at = 0", batchNo).
		Group("sku_item").
		Order("RAND()").
		Limit(sampleSize).
		Pluck("sku_item", &skuItems).Error
	if err != nil {
		return nil, err
	}

	mappingDao := microScrmDao.NewInventorySkuUpcMappingDao()
	samples := make([]compareSkuUpcSample, 0, len(skuItems))
	for _, skuItem := range skuItems {
		upcs, err := mappingDao.GetUpcCodesBySkuItem(c, enterpriseId, batchNo, skuItem)
		if err != nil {
			return nil, err
		}
		samples = append(samples, compareSkuUpcSample{
			SkuItem: skuItem,
			DbUpcs:  upcs,
		})
	}
	return samples, nil
}

func (job *CompareSkuUpcMapping) pickManualSamples(c app.Ctx, enterpriseId int64, batchNo string, skuItems []string) ([]compareSkuUpcSample, error) {
	mappingDao := microScrmDao.NewInventorySkuUpcMappingDao()
	samples := make([]compareSkuUpcSample, 0, len(skuItems))
	for _, skuItem := range skuItems {
		upcs, err := mappingDao.GetUpcCodesBySkuItem(c, enterpriseId, batchNo, skuItem)
		if err != nil {
			return nil, err
		}
		samples = append(samples, compareSkuUpcSample{
			SkuItem: skuItem,
			DbUpcs:  upcs,
		})
	}
	return samples, nil
}

func diffUpcCodes(dbUpcs, pimUpcs []string) ([]string, []string, bool) {
	dbSet := make(map[string]struct{})
	pimSet := make(map[string]struct{})
	for _, upc := range normalizeUpcCodes(dbUpcs) {
		dbSet[upc] = struct{}{}
	}
	for _, upc := range normalizeUpcCodes(pimUpcs) {
		pimSet[upc] = struct{}{}
	}

	onlyInDB := make([]string, 0)
	for upc := range dbSet {
		if _, ok := pimSet[upc]; !ok {
			onlyInDB = append(onlyInDB, upc)
		}
	}
	sort.Strings(onlyInDB)

	onlyInPIM := make([]string, 0)
	for upc := range pimSet {
		if _, ok := dbSet[upc]; !ok {
			onlyInPIM = append(onlyInPIM, upc)
		}
	}
	sort.Strings(onlyInPIM)

	return onlyInDB, onlyInPIM, len(onlyInDB) == 0 && len(onlyInPIM) == 0
}

func normalizeUpcCodes(upcs []string) []string {
	normalized := make([]string, 0, len(upcs))
	for _, upc := range upcs {
		upc = strings.TrimSpace(upc)
		if upc != "" {
			normalized = append(normalized, upc)
		}
	}
	return helper.ArrayUniq(normalized)
}

func parseManualCompareSkuItems(value string) []string {
	parts := strings.Split(value, ",")
	skuItems := make([]string, 0, len(parts))
	seen := make(map[string]struct{})
	for _, part := range parts {
		skuItem := strings.ToUpper(strings.TrimSpace(part))
		if skuItem == "" {
			continue
		}
		if _, ok := seen[skuItem]; ok {
			continue
		}
		seen[skuItem] = struct{}{}
		skuItems = append(skuItems, skuItem)
	}
	return skuItems
}
